import json
task = json.load(open("task.json"))
parts = task["parts"]

def box(p):
    x,y,z = p["target_position"]; sx,sy,sz = p["size_m"]
    return (x-sx/2, x+sx/2, y-sy/2, y+sy/2, z-sz/2, z+sz/2)

boxes = {p["index"]: box(p) for p in parts}
parts_by_idx = {p["index"]: p for p in parts}

def overlap2d(a,b):
    # boxes are (x0,x1,y0,y1,z0,z1)
    ox = min(a[1],b[1]) - max(a[0],b[0])
    oy = min(a[3],b[3]) - max(a[2],b[2])
    return ox, oy

# For each part, find which parts it rests on (below it, top touching its bottom)
eps = 1e-4
deps = {p["index"]: [] for p in parts}
for p in parts:
    b = boxes[p["index"]]
    bz0 = b[4]  # bottom z
    for q in parts:
        if q["index"] == p["index"]: continue
        c = boxes[q["index"]]
        # q's top close to p's bottom
        if abs(c[5] - bz0) < eps:
            ox, oy = overlap2d(b, c)
            if ox > 1e-5 and oy > 1e-5:
                deps[p["index"]].append(q["index"])

for i in range(len(parts)):
    print(i, "rests on", deps[i])

